import {scopedIds} from './boundary-filter.js?v=survey-map-20261017';
export function mapGeometry(g){const wkid=g?.spatialReference?.latestWkid||g?.spatialReference?.wkid;if(wkid!==4326)throw Error('Map coordinates were not returned in WGS84.');const valid=p=>Array.isArray(p)&&p.length>=2&&Number.isFinite(p[0])&&Number.isFinite(p[1])&&Math.abs(p[0])<=180&&Math.abs(p[1])<=90;if(Number.isFinite(g.x)&&valid([g.x,g.y]))return {kind:'point',coordinates:[g.y,g.x]};if(g.paths?.length&&g.paths.every(r=>r.length>=2&&r.every(valid)))return {kind:'line',coordinates:g.paths.map(r=>r.map(p=>[p[1],p[0]]))};if(g.rings?.length&&g.rings.every(r=>r.length>=4&&r.every(valid)))return {kind:'polygon',coordinates:g.rings.map(r=>r.map(p=>[p[1],p[0]]))};throw Error('Feature has no supported map geometry.');}
export function mapWhere(meta,source,users){if(users===null)return '1=1';if(!meta.fields.some(f=>f.name===source)||!/^[_a-zA-Z][_a-zA-Z0-9]*$/.test(source))throw Error('Choose a valid surveyor username field.');if(!users.length)throw Error('Select usernames or Monitor all usernames.');return source+' IN ('+users.map(u=>"'"+String(u).replace(/'/g,"''")+"'").join(',')+')';}
export async function mapLayerRecords(api,layer,bounds,spatial,users,limit=10000){const where=mapWhere(layer.meta,layer.source,users),r=await api.request(layer.url+'/query',{where,geometry:JSON.stringify({...bounds,spatialReference:{wkid:4326}}),geometryType:'esriGeometryEnvelope',inSR:4326,spatialRel:'esriSpatialRelIntersects',returnIdsOnly:true});if(r.exceededTransferLimit||!Array.isArray(r.objectIds))throw Error('Map did not receive a complete visible ID list.');if(r.objectIds.some(id=>!Number.isSafeInteger(id)||id<0))throw Error('Invalid map object IDs.');let ids=[...new Set(r.objectIds)].sort((a,b)=>a-b);if(spatial){const allowed=new Set(await scopedIds(api,layer.url,spatial));ids=ids.filter(id=>allowed.has(id));}const total=ids.length;ids=ids.slice(0,limit);const names=[...new Set([layer.meta.objectIdField,layer.source,...layer.fields,...(layer.phaseField&&layer.meta.fields.some(f=>f.name===layer.phaseField)?[layer.phaseField]:[]),...(layer.labelField&&layer.meta.fields.some(f=>f.name===layer.labelField)?[layer.labelField]:[]),layer.meta.globalIdField,...layer.meta.fields.filter(f=>f.type==='esriFieldTypeGlobalID').map(f=>f.name),layer.collected,layer.edited,layer.meta.typeIdField].filter(Boolean))],rows=[],problems=[];
 async function batch(part){if(!part.length)return;const result=await api.request(layer.url+'/query',{objectIds:part.join(','),outFields:names.join(','),returnGeometry:true,outSR:4326,...(layer.meta.datesInUnknownTimezone?{timeReferenceUnknownClient:true}:{})});const found=new Map((result.features||[]).map(f=>[f.attributes?.[layer.meta.objectIdField],f]));if(result.exceededTransferLimit||part.some(id=>!found.has(id))){if(part.length>1){const mid=Math.floor(part.length/2);await batch(part.slice(0,mid));await batch(part.slice(mid));return;}if(!found.has(part[0])){problems.push('Record '+part[0]+' unavailable');return;}}for(const id of part){const feature=found.get(id);try{if(users!==null&&!users.includes(feature.attributes[layer.source]))continue;const geometry={...feature.geometry,spatialReference:feature.geometry?.spatialReference||result.spatialReference};rows.push({...feature,geometry,shape:mapGeometry(geometry)});}catch(e){problems.push('Record '+id+': '+e.message);}}}
 const size=Math.max(1,Math.min(layer.meta.maxRecordCount||500,500));for(let i=0;i<ids.length;i+=size)await batch(ids.slice(i,i+size));return {rows,total,limited:total>ids.length,problems};}
